steps.analogousExample:
/* Example of a class selector */
.highlight {
    background-color: yellow;
    padding: 10px;
}

/* Example of element selector with conflicting style */
p {
    color: blue;
}

/* Example of an ID selector with a style rule */
#header {
    font-size: 24px;
}

/* Example: using !important to override specificity */
.some-class {
    color: blue !important;
}

/* Combining element and class selectors */
p.highlight {
    background-color: yellow;
}

/* Example of a pseudo-class selector */
p:hover {
    color: yellow;
}

/* Similar: combined selector targeting specific elements with a class */
button.primary {
    background-color: blue;
}
